<?php if ( ! defined( 'ABSPATH' ) ) { exit; } get_header(); ?>
<main class="archive-shell"><section class="archive-hero"><h1><?php post_type_archive_title(); ?></h1><p><?php esc_html_e( 'Explore countries for study, work, and relocation opportunities.', 'nvconsult-theme-v2' ); ?></p></section><section class="section" style="padding-top:24px;"><div class="archive-grid"><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); $flag=get_post_meta(get_the_ID(),'_nvconsult_flag_image',true); $description=get_post_meta(get_the_ID(),'_nvconsult_description',true); ?><article class="archive-card content-card"><?php if(has_post_thumbnail()): the_post_thumbnail('large'); endif; ?><?php if($flag): ?><div class="destination-card__flag" style="margin-top:16px;"><img src="<?php echo esc_url( $flag ); ?>" alt="<?php the_title_attribute(); ?>"></div><?php endif; ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( wp_trim_words( $description ? $description : get_the_excerpt(), 22 ) ); ?></p><a class="btn-outline" href="<?php the_permalink(); ?>"><?php esc_html_e( 'View Country', 'nvconsult-theme-v2' ); ?></a></article><?php endwhile; else : ?><div class="placeholder-message"><p><?php esc_html_e( 'No countries found yet.', 'nvconsult-theme-v2' ); ?></p></div><?php endif; ?></div><?php the_posts_pagination(); ?></section></main>
